-- 006_video_learning: durable verified video coverage and one active video owner per learner.
-- Every step has one read-only completion probe and one executable statement.

-- @step create_video_learning_record
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_record' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_record') = 13 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_record' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('user_id', 'lesson_version_id', 'duration_ms') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('credited_ms', 'coverage_ms', 'confirmed_position_ms') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'coverage_intervals' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'is_completed' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME IN ('completed_at', 'last_learn_at') AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)') OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 13 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_record') = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_record' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_video_learning_record_user_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'user_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_video_learning_record_user_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'lesson_version_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_video_learning_record_user_completed' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'user_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_video_learning_record_user_completed' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'is_completed' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_video_learning_record_version' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'lesson_version_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 6 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `video_learning_record` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED NOT NULL, `lesson_version_id` BIGINT UNSIGNED NOT NULL, `duration_ms` BIGINT UNSIGNED NOT NULL COMMENT '不可变课时版本时长快照', `credited_ms` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '有效播放时长，可含重复观看', `coverage_intervals` JSON NOT NULL COMMENT '已确认去重播放区间，毫秒', `coverage_ms` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '去重覆盖毫秒', `confirmed_position_ms` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '最远已确认断点', `is_completed` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '覆盖达到 95%', `completed_at` DATETIME(3) NULL, `last_learn_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_video_learning_record_user_version` (`user_id`, `lesson_version_id`), KEY `idx_video_learning_record_user_completed` (`user_id`, `is_completed`), KEY `idx_video_learning_record_version` (`lesson_version_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学员视频版本学习汇总';

-- @step create_video_learning_session
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_session' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_session') = 12 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_session' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('record_id', 'user_id', 'lesson_version_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'active_user_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME IN ('started_at', 'last_heartbeat_at') AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'ended_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'last_seq' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME IN ('anchor_position_ms', 'credited_ms') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'anchor_state' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'playing'))) = 12 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_session') = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'video_learning_session' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_video_learning_session_active_user' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'active_user_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_video_learning_session_user_started' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'user_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_video_learning_session_user_started' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'started_at' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_video_learning_session_last_heartbeat' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'last_heartbeat_at' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_video_learning_session_record' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'record_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 6 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `video_learning_session` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `record_id` BIGINT UNSIGNED NOT NULL, `user_id` BIGINT UNSIGNED NOT NULL, `lesson_version_id` BIGINT UNSIGNED NOT NULL, `active_user_id` BIGINT UNSIGNED NULL COMMENT '活动所有者；结束后置 NULL', `started_at` DATETIME(3) NOT NULL, `last_heartbeat_at` DATETIME(3) NOT NULL, `ended_at` DATETIME(3) NULL, `last_seq` INT UNSIGNED NOT NULL DEFAULT 0, `anchor_position_ms` BIGINT UNSIGNED NOT NULL DEFAULT 0, `anchor_state` VARCHAR(32) NOT NULL DEFAULT 'playing' COMMENT 'playing / paused / buffering / background / ended', `credited_ms` BIGINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY (`id`), UNIQUE KEY `uk_video_learning_session_active_user` (`active_user_id`), KEY `idx_video_learning_session_user_started` (`user_id`, `started_at`), KEY `idx_video_learning_session_last_heartbeat` (`last_heartbeat_at`), KEY `idx_video_learning_session_record` (`record_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='可恢复视频学习会话';
